import android.content.Intent;
import com.joaomgcd.taskerm.action.java.JavaCodeException;

/* Create an intent to pick an image using the system document picker. */
intent = new Intent(Intent.ACTION_GET_CONTENT);
intent.setType("image/*");
intent.addCategory(Intent.CATEGORY_OPENABLE);

try {
    /* Start the activity and get a Single that will emit the result Intent. */
    resultIntent = (Intent) tasker.getWithActivityForResult(intent).blockingGet();

    /* Get the URI of the selected image from the result Intent. */
    imageUri = resultIntent.getData();

    if (imageUri == null) {
        throw new JavaCodeException("No image was selected.");
    }

    /* Return the URI as a string. */
    return imageUri.toString();
} catch (Exception e) {
    /* Handle the specific error case requested. */
    throw new JavaCodeException("Couldn't get result");
}

import android.content.Intent;
import android.net.Uri;
import com.joaomgcd.taskerm.action.java.JavaCodeException;

/* Create an intent to pick an image using the system document picker. */
intent = new Intent(Intent.ACTION_OPEN_DOCUMENT);
intent.addCategory(Intent.CATEGORY_OPENABLE);
intent.setType("image/*");

/* 
 * Add EXTRA_LOCAL_ONLY to restrict the picker to local files 
 * and hide cloud/remote storage providers. 
 */
intent.putExtra(Intent.EXTRA_LOCAL_ONLY, true);

try {
    /* Start the activity and get a Single that will emit the result Intent. */
    resultIntent = (Intent) tasker.getWithActivityForResult(intent).blockingGet();

    /* Get the URI of the selected image from the result Intent. */
    imageUri = resultIntent.getData();

    if (imageUri == null) {
        throw new JavaCodeException("No image was selected.");
    }

    /* Return the URI as a string. */
    return imageUri.toString();
} catch (Exception e) {
    /* Handle the specific error case requested. */
    throw new JavaCodeException("Couldn't get result");
}

import android.provider.Settings;
import com.joaomgcd.taskerm.action.java.JavaCodeException;

/* Retrieve the package name variable from Tasker. */
karen_package = tasker.getVariable("karen_package");

if (karen_package == null) {
    throw new JavaCodeException("Variable %karen_package is not set.");
}

/* Construct the full service component string. */
service_value = karen_package + "/com.joaomgcd.taskerm.assistant.ServiceVoiceInteractionTasker";

/* 
 * Attempt to write to Secure Settings. 
 * Note: This requires the WRITE_SECURE_SETTINGS permission to be granted 
 * via ADB or a similar mechanism beforehand, as requested. 
 * Tasker's 'Custom Setting' action or direct provider access is used here.
 */
try {
    Settings.Secure.putString(context.getContentResolver(), "voice_interaction_service", service_value);
} catch (Exception e) {
    throw new JavaCodeException("Failed to set %karen_package app as default assistant app because WRITE_SECURE_SETTINGS permission is not granted.");
}

