import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import android.security.keystore.KeyGenParameterSpec;
import android.security.keystore.KeyProperties;
import java.security.KeyStore;
import android.util.Base64;

String ALIAS = "KarenKeyAlias";

String apiKey = tasker.getVariable("input");
if (apiKey == null || apiKey.isEmpty()) {
    throw new RuntimeException("input is empty!");
}

/* Create or retrieve key from Keystore */
KeyStore ks = KeyStore.getInstance("AndroidKeyStore");
ks.load(null);

if (!ks.containsAlias(ALIAS)) {
    KeyGenerator keyGen = KeyGenerator.getInstance(
        KeyProperties.KEY_ALGORITHM_AES, "AndroidKeyStore");
    keyGen.init(new KeyGenParameterSpec.Builder(
        ALIAS,
        KeyProperties.PURPOSE_ENCRYPT | KeyProperties.PURPOSE_DECRYPT)
        .setBlockModes(KeyProperties.BLOCK_MODE_GCM)
        .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE)
        .build());
    keyGen.generateKey();
}

SecretKey secretKey = ((KeyStore.SecretKeyEntry) ks.getEntry(ALIAS, null)).getSecretKey();

/* Enkripsi */
Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
cipher.init(Cipher.ENCRYPT_MODE, secretKey);
byte[] iv        = cipher.getIV();
byte[] encrypted = cipher.doFinal(apiKey.getBytes("UTF-8"));

/* Convert to Base64 string → save to Tasker variable */
String encStr = Base64.encodeToString(encrypted, Base64.NO_WRAP);
String ivStr  = Base64.encodeToString(iv, Base64.NO_WRAP);

tasker.setVariable("KENC", encStr);
tasker.setVariable("KIV", ivStr);

/* Erase plaintext from memory */
tasker.setVariable("input", "");

tasker.log("API key successfully encrypted to KENC and KIV.");

