import android.content.Intent;
import android.content.Context;
import android.app.StatusBarManager;

/* 
 * The StatusBarManager is a system service that allows controlling the status bar.
 * Note: This requires the EXPAND_STATUS_BAR permission, which is granted to 
 * system-level apps or apps with specific signatures. In Tasker, this 
 * functionality is often restricted by Android's security model.
 */

try {
    /* Get the status bar service from the context. */
    statusBarService = context.getSystemService("statusbar");

    /* 
     * Use reflection to call the hidden 'expandNotificationsPanel' method.
     * Since we cannot use standard reflection classes, we rely on the 
     * BeanShell interpreter's ability to invoke methods dynamically.
     */
    statusBarService.expandNotificationsPanel();
} catch (Exception e) {
    /* 
     * If the method is not accessible or the permission is missing, 
     * this will fail. This is expected behavior on most modern Android 
     * versions without specific system privileges.
     */
    tasker.log("Error: Unable to expand status bar. Permission or API restriction.");
}

import android.content.Intent;
import android.provider.Settings;
import android.net.Uri;
import com.joaomgcd.taskerm.action.java.JavaCodeException;

/* 
 * Requesting to ignore battery optimizations requires the user to manually 
 * grant the permission in the system settings. 
 */

String packageName = context.getPackageName();

/* 
 * Check if the app already has permission to ignore battery optimizations. 
 * This requires the REQUEST_IGNORE_BATTERY_OPTIMIZATIONS permission in the manifest.
 */
powerManager = context.getSystemService(android.content.Context.POWER_SERVICE);
if (powerManager.isIgnoringBatteryOptimizations(packageName)) {
    tasker.log("Battery optimization is already ignored for this app.");
    return;
}

/* 
 * Create an intent to open the specific system settings page for this app.
 * This is the only way to request this permission without root/adb/shizuku.
 */
intent = new Intent(Settings.ACTION_REQUEST_IGNORE_BATTERY_OPTIMIZATIONS);
intent.setData(Uri.parse("package:" + packageName));
intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);

try {
    context.startActivity(intent);
    tasker.log("Opened battery optimization settings for user action.");
} catch (Exception e) {
    throw new JavaCodeException("Could not open battery settings: " + e.getMessage());
}

