import android.content.Intent;
import android.content.pm.PackageManager;
import android.content.pm.ResolveInfo;
import java.util.ArrayList;
import java.util.List;

/* Create an intent to find all apps that have a launcher activity. */
intent = new Intent(Intent.ACTION_MAIN, null);
intent.addCategory(Intent.CATEGORY_LAUNCHER);

/* Get the package manager from the context. */
pm = context.getPackageManager();

/* Query the package manager for all matching activities. */
activities = pm.queryIntentActivities(intent, 0);

/* Create a list to store the app names. */
appNames = new ArrayList();

/* Iterate through the results and extract the human-readable labels. */
for (int i = 0; i < activities.size(); i++) {
    ResolveInfo info = (ResolveInfo) activities.get(i);
    appNames.add(info.loadLabel(pm).toString());
}

/* Build a comma-separated string of app names. */
sb = new StringBuilder();
for (int i = 0; i < appNames.size(); i++) {
    sb.append((String) appNames.get(i));
    if (i < appNames.size() - 1) {
        sb.append(",");
    }
}

/* Return the comma-separated string. */
return sb.toString();

import android.content.Intent;
import android.content.pm.PackageManager;
import android.content.pm.ResolveInfo;
import java.util.ArrayList;
import java.util.List;

/* Create an intent to find all apps that have a launcher activity. */
intent = new Intent(Intent.ACTION_MAIN, null);
intent.addCategory(Intent.CATEGORY_LAUNCHER);

/* Get the package manager from the context. */
pm = context.getPackageManager();

/* Query the package manager for all matching activities. */
activities = pm.queryIntentActivities(intent, 0);

/* Create a list to store the package names. */
packageNames = new ArrayList();

/* Iterate through the results and extract the package names. */
for (int i = 0; i < activities.size(); i++) {
    ResolveInfo info = (ResolveInfo) activities.get(i);
    packageNames.add(info.activityInfo.packageName);
}

/* Build a comma-separated string of package names. */
sb = new StringBuilder();
for (int i = 0; i < packageNames.size(); i++) {
    sb.append((String) packageNames.get(i));
    if (i < packageNames.size() - 1) {
        sb.append(",");
    }
}

/* Return the comma-separated string. */
return sb.toString();

import android.content.Context;
import android.content.Intent;
import android.content.pm.ApplicationInfo;
import android.content.pm.PackageManager;
import android.content.pm.ResolveInfo;
import java.util.ArrayList;
import java.util.List;

/* Get the package manager instance. */
pm = context.getPackageManager();
disabledLaunchableAppNames = new ArrayList();

/* Query all activities that have the launcher category. */
mainIntent = new Intent(Intent.ACTION_MAIN, null);
mainIntent.addCategory(Intent.CATEGORY_LAUNCHER);

/* Retrieve all activities, including disabled ones. */
allActivities = pm.queryIntentActivities(mainIntent, PackageManager.GET_DISABLED_COMPONENTS | PackageManager.GET_RESOLVED_FILTER);

/* Iterate through the list using a standard index-based loop. */
for (int i = 0; i < allActivities.size(); i++) {
    resolveInfo = (ResolveInfo) allActivities.get(i);
    appInfo = resolveInfo.activityInfo.applicationInfo;

    /* Check if the application is disabled. */
    if (!appInfo.enabled) {
        /* Retrieve the human-readable label of the application. */
        appName = pm.getApplicationLabel(appInfo).toString();

        /* Add the app name to the list if not already present. */
        if (!disabledLaunchableAppNames.contains(appName)) {
            disabledLaunchableAppNames.add(appName);
        }
    }
}

/* Return the list of app names as a comma-separated string for Tasker. */
result = "";
for (int i = 0; i < disabledLaunchableAppNames.size(); i++) {
    result = result + (String) disabledLaunchableAppNames.get(i);
    if (i < disabledLaunchableAppNames.size() - 1) {
        result = result + ",";
    }
}

return result;

import android.content.Context;
import android.content.Intent;
import android.content.pm.ApplicationInfo;
import android.content.pm.PackageManager;
import android.content.pm.ResolveInfo;
import java.util.ArrayList;
import java.util.List;

/* Get the package manager instance. */
pm = context.getPackageManager();
disabledLaunchablePackages = new ArrayList();

/* Query all activities that have the launcher category. */
mainIntent = new Intent(Intent.ACTION_MAIN, null);
mainIntent.addCategory(Intent.CATEGORY_LAUNCHER);

/* Retrieve all activities, including disabled ones. */
allActivities = pm.queryIntentActivities(mainIntent, PackageManager.GET_DISABLED_COMPONENTS | PackageManager.GET_RESOLVED_FILTER);

/* Iterate through the list using a standard index-based loop. */
for (int i = 0; i < allActivities.size(); i++) {
    resolveInfo = (ResolveInfo) allActivities.get(i);
    appInfo = resolveInfo.activityInfo.applicationInfo;

    /* Check if the package is disabled. */
    if (!appInfo.enabled) {
        /* Add the package name to the list if not already present. */
        if (!disabledLaunchablePackages.contains(appInfo.packageName)) {
            disabledLaunchablePackages.add(appInfo.packageName);
        }
    }
}

/* Return the list of package names as a comma-separated string for Tasker. */
result = "";
for (int i = 0; i < disabledLaunchablePackages.size(); i++) {
    result = result + (String) disabledLaunchablePackages.get(i);
    if (i < disabledLaunchablePackages.size() - 1) {
        result = result + ",";
    }
}

return result;

